// This file is generated by AI.

import { describe, expect, it } from 'vitest';

import { preprocess } from '../src/pipeline';

function proc(raw: string): string {
  return preprocess(raw).intermediate;
}

describe('preprocess 旁白', () => {
  it('普通旁白加冒号前缀 (附原句注释)', () => {
    expect(proc('今天天气很好。')).toBe('; 今天天气很好。\n:今天天气很好。');
  });

  it('英文标点转中文 + 空格规范', () => {
    expect(proc('价格是12%的人。')).toBe('; 价格是12%的人。\n:价格是 12% 的人。');
  });

  it('小数点不被误转', () => {
    expect(proc('圆周率是3.14。')).toBe('; 圆周率是3.14。\n:圆周率是 3.14。');
  });

  it('句中嵌套引号保持旁白', () => {
    expect(proc('他突然说“你好”然后走了。')).toBe('; 他突然说“你好”然后走了。\n:他突然说“你好”然后走了。');
  });

  it('空行被去除', () => {
    expect(proc('第一段。\n\n\n第二段。')).toBe('; 第一段。\n:第一段。\n; 第二段。\n:第二段。');
  });
});

describe('preprocess 对话', () => {
  it('简单对话', () => {
    expect(proc('“你好。”')).toBe('; “你好。”\n%:你好。');
  });

  it('句内单引号提升为双引号', () => {
    expect(proc('“他说‘你好’。”')).toBe('; “他说‘你好’。”\n%:他说“你好”。');
  });

  it('里外都用双引号时识别嵌套', () => {
    expect(proc('“他说“你好”然后走了。”')).toBe('; “他说“你好”然后走了。”\n%:他说“你好”然后走了。');
  });

  it('对话 + 旁白尾拆分为两行', () => {
    expect(proc('“那是……？”她指着沙发角落里一个粉粉的玩意。')).toBe(
      '; “那是……？”她指着沙发角落里一个粉粉的玩意。\n%:那是……？\n:她指着沙发角落里一个粉粉的玩意。'
    );
  });

  it('多个对话与旁白交替识别', () => {
    expect(proc('“我不知道。”她看着窗外西沉的太阳。“但是我知道你该走了。”')).toBe(
      '; “我不知道。”她看着窗外西沉的太阳。“但是我知道你该走了。”\n%:我不知道。\n:她看着窗外西沉的太阳。\n%:但是我知道你该走了。'
    );
  });

  it('跨行对话合并为跟随', () => {
    expect(proc('“你好。\n“我叫小明。”')).toBe('; “你好。\n%:你好。\n我叫小明。');
  });

  it('对话断句后保持跟随', () => {
    expect(proc('“今天天气真不错。我们去公园散步吧？好呀！”')).toBe(
      '; “今天天气真不错。我们去公园散步吧？好呀！”\n%:今天天气真不错。\n我们去公园散步吧？\n好呀！'
    );
  });

  it('引语前缀拆成旁白 + 对话', () => {
    expect(proc('他说：“你好。”')).toBe('; 他说：“你好。”\n:他说\n%:你好。');
    expect(proc('，他说道：“快走！”')).toBe('; ，他说道：“快走！”\n:他说道\n%:快走！');
  });
});

describe('preprocess 断句', () => {
  it('超长句在逗号断开', () => {
    const raw = '一二三四五六七八九十一二三四五六七八九十，二二三四五六七八九十二二三四五六七八九十。';
    expect(proc(raw)).toBe(
      `; ${raw}\n:一二三四五六七八九十一二三四五六七八九十\n:二二三四五六七八九十二二三四五六七八九十。`
    );
  });

  it('超长句无中间标点则不切', () => {
    const raw = '一二三四五六七八九十一二三四五六七八九十一二三四五六七八九十。';
    expect(proc(raw)).toBe(`; ${raw}\n:${raw}`);
  });

  it('连续非中文块不断句', () => {
    expect(proc('assa!!!!!')).toBe('; assa!!!!!\n:assa!!!!!');
  });

  it('连续结束标点不断句 (省略号 + 问号)', () => {
    expect(proc('那是……？')).toBe('; 那是……？\n:那是……？');
  });

  it('过短相邻句合并', () => {
    expect(proc('他。走。')).toBe('; 他。走。\n:他。走。');
  });
});
